<!--
 * 角色管理页面 — 展示角色列表，支持新增/编辑/删除角色及权限分配
 *
 * @path apps\userinfo-web\src\views\system\role\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 角色（列表页）
 * <p>角色（{@code ydsz_role}）的列表页，消费后端契约 RoleController
 * （src/api/role.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询角色，支持新增/编辑/删除，以及基于菜单树的权限分配
 * （getRolePermissions / assignPermissions，菜单来源 menu.tree()）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import {
  ElButton,
  ElDialog,
  ElMessage,
  ElMessageBox,
  ElTable,
  ElTableColumn,
  ElTag,
  ElTransfer,
} from 'element-plus';
import { h, onMounted, ref } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { tree as menuTree } from '#/api/menu';
import type { MenuTreeVO, UserAccountVO } from '#/api/models';
import { page as userPage } from '#/api/userAccount';
import { assignPermissions, create, getById, getRolePermissions, page, remove } from '#/api/role';
import type { RoleVO } from '#/api/models';

import RoleForm from './role-form.vue';

defineOptions({ name: 'RoleManagement' });

/** 判断角色状态是否启用（契约 status 为字符串 '1'/'0'） */
function isEnabled(status?: string): boolean {
  return status === '1';
}

const gridOptions: VxeTableGridOptions<RoleVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'roleName', title: '角色名称', width: 150 },
    { field: 'roleCode', title: '角色编码', width: 150 },
    { field: 'sortOrder', title: '排序', width: 80, align: 'center' },
    {
      field: 'builtIn',
      title: '内置',
      width: 80,
      slots: {
        default: ({ row }) =>
          row.builtIn ? h(ElTag, { type: 'info', size: 'small' }, () => '内置') : h('span', null, '自定义'),
      },
    },
    {
      field: 'status',
      title: '状态',
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            ElTag,
            { type: enable ? 'success' : 'danger', size: 'small' },
            () => (enable ? '启用' : '禁用'),
          );
        },
      },
    },
    { field: 'description', title: '描述', minWidth: 160 },
    {
      field: 'action',
      title: '操作',
      width: 320,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) },
              () => '编辑',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'warning', onClick: () => handleAssignPermissions(row) },
              () => '分配权限',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'info', onClick: () => handleCopyRole(row) },
              () => '复制',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'success', onClick: () => handleViewUsers(row) },
              () => '用户',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => '删除',
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'Input',
        componentProps: { placeholder: '角色名称' },
        fieldName: 'roleName',
        label: '角色名称',
      },
      {
        component: 'Input',
        componentProps: { placeholder: '角色编码' },
        fieldName: 'roleCode',
        label: '角色编码',
      },
      {
        component: 'Select',
        componentProps: {
          placeholder: '状态',
          options: [
            { label: '启用', value: '1' },
            { label: '禁用', value: '0' },
          ],
        },
        fieldName: 'status',
        label: '状态',
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: '搜索' },
    resetButtonOptions: { content: '重置' },
  },
});

// ========== 表单弹窗 ==========
const [RoleFormModal, roleFormApi] = useYDSZModal({ connectedComponent: RoleForm });

function handleAdd() {
  roleFormApi.open();
}

function handleEdit(row: RoleVO) {
  roleFormApi.setData({ record: row });
  roleFormApi.open();
}

// ========== 权限分配 ==========
const permDialogVisible = ref(false);
const currentRoleId = ref('');
const currentRoleName = ref('');
const selectedPermIds = ref<string[]>([]);
const permTransferData = ref<{ label: string; key: string }[]>([]);

/** 将菜单树拍平为穿梭框可选数据（label 展示菜单名+权限标识） */
function flattenMenuTree(nodes: MenuTreeVO[]): { label: string; key: string }[] {
  const result: { label: string; key: string }[] = [];
  nodes.forEach((node) => {
    if (node.id) {
      result.push({
        label: `${node.menuName ?? ''}${node.permissionCode ? ` (${node.permissionCode})` : ''}`,
        key: node.id,
      });
    }
    if (node.children?.length) {
      result.push(...flattenMenuTree(node.children));
    }
  });
  return result;
}

const menuTreeData = ref<MenuTreeVO[]>([]);

async function loadMenuTree() {
  try {
    menuTreeData.value = (await menuTree()) ?? [];
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

onMounted(loadMenuTree);

async function handleAssignPermissions(row: RoleVO) {
  if (!row.id) return;
  currentRoleId.value = row.id;
  currentRoleName.value = row.roleName ?? '';
  permTransferData.value = flattenMenuTree(menuTreeData.value);
  try {
    selectedPermIds.value = (await getRolePermissions({ roleId: row.id })) ?? [];
  } catch {
    // 错误提示由请求拦截器统一处理
  }
  permDialogVisible.value = true;
}

async function confirmPermissionAssign() {
  try {
    await assignPermissions(
      { roleId: currentRoleId.value },
      { permissionIds: selectedPermIds.value },
    );
    ElMessage.success('权限分配成功');
    permDialogVisible.value = false;
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

// ========== 删除 ==========
async function handleDelete(row: RoleVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(
      `确定删除角色「${row.roleName ?? ''}」吗？`,
      '删除确认',
      { type: 'warning' },
    );
  } catch {
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await remove({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}

// ========== 复制角色 ==========
async function handleCopyRole(row: RoleVO): Promise<void> {
  if (!row.id) return;
  try {
    // 获取源角色详情
    const sourceRole = await getById({ id: row.id });
    // 创建新角色（复制属性，修改名称和编码）
    const newRoleId = await create({
      roleName: `${sourceRole.roleName ?? ''}_副本`,
      roleCode: `${sourceRole.roleCode ?? ''}_COPY_${Date.now()}`,
      description: sourceRole.description,
      sortOrder: sourceRole.sortOrder,
      dataScope: sourceRole.dataScope,
      status: sourceRole.status,
      tenantId: sourceRole.tenantId,
    });
    // 复制权限
    const permissions = await getRolePermissions({ roleId: row.id });
    if (permissions.length > 0 && newRoleId) {
      await assignPermissions({ roleId: newRoleId }, { permissionIds: permissions });
    }
    ElMessage.success('角色复制成功');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

// ========== 角色用户列表 ==========
const userListDialogVisible = ref(false);
const roleUserList = ref<UserAccountVO[]>([]);
const currentViewRoleName = ref('');

async function handleViewUsers(row: RoleVO): Promise<void> {
  if (!row.id) return;
  currentViewRoleName.value = row.roleName ?? '';
  userListDialogVisible.value = true;
  try {
    const res = await userPage({
      query: { roleIds: row.id },
    });
    roleUserList.value = res.data ?? [];
  } catch {
    roleUserList.value = [];
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="角色管理">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">新增角色</ElButton>
      </template>
    </Grid>
    <RoleFormModal @success="gridApi.query()" />

    <ElDialog
      v-model="permDialogVisible"
      :title="`分配权限 - ${currentRoleName}`"
      width="600px"
    >
      <ElTransfer
        v-model="selectedPermIds"
        :data="permTransferData"
        :titles="['可选权限', '已分配权限']"
        filterable
        filter-placeholder="搜索权限"
      />
      <template #footer>
        <ElButton @click="permDialogVisible = false">取消</ElButton>
        <ElButton type="primary" @click="confirmPermissionAssign">确定</ElButton>
      </template>
    </ElDialog>

    <!-- 角色用户列表弹窗 -->
    <ElDialog
      v-model="userListDialogVisible"
      :title="`角色用户 - ${currentViewRoleName}`"
      width="800px"
    >
      <ElTable :data="roleUserList" border max-height="400">
        <ElTableColumn type="index" label="序号" width="60" />
        <ElTableColumn prop="username" label="用户名" width="120" />
        <ElTableColumn prop="realName" label="姓名" width="120" />
        <ElTableColumn prop="phone" label="手机号" width="130" />
        <ElTableColumn prop="email" label="邮箱" width="180" />
        <ElTableColumn prop="status" label="状态" width="80">
          <template #default="{ row }">
            <ElTag :type="row.status === 1 ? 'success' : 'danger'" size="small">
              {{ row.status === 1 ? '启用' : '禁用' }}
            </ElTag>
          </template>
        </ElTableColumn>
        <ElTableColumn prop="createdAt" label="创建时间" width="170" />
      </ElTable>
      <template #footer>
        <ElButton @click="userListDialogVisible = false">关闭</ElButton>
      </template>
    </ElDialog>
  </Page>
</template>